/**
 * Demo script for submitting V8 Energy Drink review
 * This replicates the functionality seen in the auto_submit_v8_review.js file
 */

// Review data
const V8_REVIEW_DATA = {
    product: "V8 Energy Drink - Pomegranate Blueberry",
    rating: 5,
    reviewText: "Great energy drink! The pomegranate blueberry flavor is refreshing and the energy boost from green tea is smooth and sustained. Highly recommend for anyone looking for a healthier energy option."
};

/**
 * Simulate submitting a review for V8 Energy Drink
 */
function submitV8Review() {
    console.log("Starting V8 Energy Drink review submission...");

    // In a real browser environment, this would interact with DOM elements
    // For this demo, we'll just log the actions

    console.log(`Selecting ${V8_REVIEW_DATA.rating}-star rating`);
    console.log("Filling review text:", V8_REVIEW_DATA.reviewText);

    // Simulate form submission
    console.log("Submitting review form...");

    // Display success message
    console.log("✅ Review submitted successfully!");
    console.log("Product:", V8_REVIEW_DATA.product);
    console.log("Rating:", "★".repeat(V8_REVIEW_DATA.rating));
    console.log("Review:", V8_REVIEW_DATA.reviewText);

    return {
        success: true,
        product: V8_REVIEW_DATA.product,
        rating: V8_REVIEW_DATA.rating,
        reviewText: V8_REVIEW_DATA.reviewText
    };
}

/**
 * Enhanced version that would work with actual form elements
 */
function submitV8ReviewToForm() {
    try {
        // Check if we're in a browser environment with the form
        if (typeof document === 'undefined') {
            console.log("Running in non-browser environment, using simulation");
            return submitV8Review();
        }

        console.log("Attempting to submit review to actual form...");

        // Try to find and fill form elements
        const ratingElement = document.querySelector('input[name="rating"][value="5"]');
        const reviewElement = document.getElementById('review-text');
        const formElement = document.getElementById('review-form');

        if (ratingElement) {
            ratingElement.checked = true;
            console.log("Selected 5-star rating");
        }

        if (reviewElement) {
            reviewElement.value = V8_REVIEW_DATA.reviewText;
            console.log("Filled review text");
        }

        if (formElement) {
            // Create and dispatch submit event
            const event = new Event('submit', { cancelable: true, bubbles: true });
            formElement.dispatchEvent(event);
            console.log("Form submitted");
        }

        console.log("✅ Review submission process completed");
        return { success: true };

    } catch (error) {
        console.error("Error during review submission:", error.message);
        return { success: false, error: error.message };
    }
}

// Run the submission when the script loads
console.log("V8 Energy Drink Review Submission Script Loaded");
console.log("To submit review, call: submitV8Review() or submitV8ReviewToForm()");

